INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷289·乾祐三年·年末处置", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/57e21ee3cc42021b75390decc78b600e3618c9fb/content/books/zizhi-tongjian/vol-289/year-0950/part-13/sources/library/tongjian-289-950-last-december/source.txt", "note": "《资治通鉴》卷289·乾祐三年·年末处置，段落 zizhi-tongjian-a63549944a71-p003440；已核上下文及传主，纸本及异文待核。", "id": "8e340588-f362-58d9-bdb7-7ce5543e816b"}, {"title": "新五代史·卷11·周本纪·十二月北返与监国", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/57e21ee3cc42021b75390decc78b600e3618c9fb/content/books/zizhi-tongjian/vol-289/year-0950/part-13/sources/library/xinwudaishi-011-december-950/source.txt", "note": "《新五代史》卷11·周本纪·十二月北返与监国，段落 xin-wudaishi-b08f244b9241-p000367；已核上下文及传主，纸本及异文待核。", "id": "becceed3-0d3e-5ed2-adf2-777205288c13"}, {"title": "新五代史·卷18·刘赟传·被废诰令", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/57e21ee3cc42021b75390decc78b600e3618c9fb/content/books/zizhi-tongjian/vol-289/year-0950/part-13/sources/library/xinwudaishi-018-yun-deposed/source.txt", "note": "《新五代史》卷18·刘赟传·被废诰令，段落 xin-wudaishi-b08f244b9241-p000628；已核上下文及传主，纸本及异文待核。", "id": "f2ccc845-9824-5ae1-99d0-904b4c422070"}, {"title": "新五代史·卷18·刘赟传·拘禁与杀其随从", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/57e21ee3cc42021b75390decc78b600e3618c9fb/content/books/zizhi-tongjian/vol-289/year-0950/part-13/sources/library/xinwudaishi-018-yun-detained/source.txt", "note": "《新五代史》卷18·刘赟传·拘禁与杀其随从，段落 xin-wudaishi-b08f244b9241-p000627；已核上下文及传主，纸本及异文待核。", "id": "7d4712b4-7c39-5f5d-94fb-94e679b4e83d"}, {"title": "新五代史·卷18·刘赟传·宋州夺兵", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/57e21ee3cc42021b75390decc78b600e3618c9fb/content/books/zizhi-tongjian/vol-289/year-0950/part-13/sources/library/xinwudaishi-018-yun-songzhou/source.txt", "note": "《新五代史》卷18·刘赟传·宋州夺兵，段落 xin-wudaishi-b08f244b9241-p000626；已核上下文及传主，纸本及异文待核。", "id": "3fa9a58c-229e-5f02-9727-adf47f22dc0e"}, {"title": "新五代史·卷65·南汉世家·刘晟时内侍掌权概述", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/57e21ee3cc42021b75390decc78b600e3618c9fb/content/books/zizhi-tongjian/vol-289/year-0950/part-13/sources/library/xinwudaishi-065-liu-sheng-court/source.txt", "note": "《新五代史》卷65·南汉世家·刘晟时内侍掌权概述，段落 xin-wudaishi-b08f244b9241-p003286；已核上下文及传主，纸本及异文待核。", "id": "d98953f6-9674-5c65-9946-438311786049"}, {"title": "资治通鉴·卷289·乾祐三年·楚王更替与迎嗣", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4036ee803f0476e08112a5a3782bf4ceb782f41e/content/books/zizhi-tongjian/vol-289/year-0950/part-12/sources/library/tongjian-289-950-chu-yun-north/source.txt", "note": "《资治通鉴》卷289·乾祐三年·楚王更替与迎嗣，段落 zizhi-tongjian-a63549944a71-p003439；已核上下文及传主，纸本及异文待核。", "id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"title": "旧五代史·卷103·隐帝本纪·十二月北征与任命", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b7c52ba6cde22f73d5e0bc2ffea0ec77f628d107/content/books/zizhi-tongjian/vol-289/year-0950/part-11/sources/library/jiuwudaishi-103-december-expedition/source.txt", "note": "《旧五代史》卷103·隐帝本纪·十二月北征与任命，段落 jiu-wudaishi-205deb4a7860-p002502；已核上下文及传主，纸本及异文待核。", "id": "58b01b09-5220-5d32-93ca-6bbb7fcb25bb"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "窦贞固", "aliases": ["竇貞固"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：窦贞固，原节度推官、获任者。", "biography": null, "status": "draft", "id": "628caf07-3ba2-5bc4-8630-598667f5bdd0"}, {"name": "刘赟", "aliases": ["劉赟", "劉贇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的儿子，刘知远喜爱他，把他当作自己的儿子。《新五代史》记948年任徐州节度使，949年《通鉴》记以武宁节度使身份获加同平章事。后续经历随主书年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "8b95e2f2-9627-55f8-adca-a0b287179971"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}, {"name": "郭崇威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州马军都指挥使，金城人。937年条中记载他不愿臣服契丹，独自南归。", "biography": null, "status": "draft", "id": "2f1d1823-9873-5df8-83ed-7330578213e6"}, {"name": "马铎", "aliases": ["马鐸", "馬鐸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "前申州刺史。950年十二月受派率兵到许州巡检，随后率军入城，刘信在惶恐中自杀。生卒年未载。", "biography": null, "status": "draft", "id": "a6837216-507d-5782-80f0-71e5a5cd719d"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "张令超", "aliases": ["張令超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘赟的护圣指挥使。950年十二月在宋州率部护卫刘赟，受到郭崇威暗中招诱后率部归附郭崇威。生卒年未载。", "biography": null, "status": "draft", "id": "8facd8ea-53e0-5d1f-838f-64649222b1d2"}, {"name": "董裔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 950, "description": "刘赟的徐州判官。950年在宋州建议刘赟夺郭崇威兵、招募士卒逃往晋阳，刘赟犹豫未决，未实行该计划；随后在刘赟被拘禁时遭杀害。生年未载。", "biography": null, "status": "draft", "id": "3f176959-9c9e-523d-b08c-e2a0f2b71309"}, {"name": "赵远", "aliases": ["趙遠", "赵上交", "趙上交"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵远，六军判官、司谏郎中、谏者。", "biography": null, "status": "draft", "id": "cb4acc0b-f3ec-52fa-9349-c01b93a95023"}, {"name": "王度", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉枢密直学士。950年与冯道、赵上交奉郭威奏请之命，到徐州迎接被选为嗣君的刘赟。是否与同名人物有关尚无证据，生卒年未载。", "biography": null, "status": "draft", "id": "4536f603-ebc8-5fc6-8b26-25924874f594"}, {"name": "贾贞", "aliases": ["賈貞", "贾正", "賈正"], "era": "五代十国", "birth_year": null, "death_year": 950, "description": "刘赟的客将，950年宋州局势紧张时以眼色示意想杀冯道，被刘赟制止；随后遭郭崇威一方杀害。《新五代史》同一客将、辞别和被杀场景写贾正，保留别名。生年未载。", "biography": null, "status": "draft", "id": "657145bb-5bc7-5e9b-b48a-19533dac2698"}, {"name": "刘福（刘赟将领）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《新五代史》刘赟传所记牙内都虞候。刘赟在宋州被拘禁时，与董裔、贾正、夏昭度等遭杀害。与同名人物无同人证据，生卒年月未定。", "biography": null, "status": "draft", "id": "72d13e27-7c0a-5cb0-a680-e254764c8497"}, {"name": "夏昭度", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《新五代史》刘赟传所记孔目官。刘赟在宋州被拘禁时，与董裔、贾正、刘福等遭杀害。生卒年月未定。", "biography": null, "status": "draft", "id": "5776f18b-6428-5b2c-89de-0b0842bab2c9"}, {"name": "刘信（刘知远从弟）", "aliases": ["劉信（劉知遠從弟）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的从弟，后汉将领。947年领义成节度使，兼侍卫马军都指挥使。与先前吴国将领刘信分别建档，生卒年尚未录入。", "biography": null, "status": "draft", "id": "a2f0a9f1-8401-5b6c-9a1e-3a49051af567"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "卢琼仙", "aliases": ["盧瓊仙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉宫人。950年与黄琼芝获刘晟任命为女侍中，穿戴朝服冠带，参与决断政务。《新五代史》还记她与宦官林延遇掌权。生卒年未载。", "biography": null, "status": "draft", "id": "a2133a6f-b390-5ac5-b489-d0b07733adf8"}, {"name": "黄琼芝", "aliases": ["黃瓊芝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉宫人。950年与卢琼仙获刘晟任命为女侍中，穿戴朝服冠带，参与决断政务。生卒年未载。", "biography": null, "status": "draft", "id": "da484e84-c9a3-5a41-adc8-e9c0f14bd084"}, {"name": "林延遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：林延遇，闽清宦者、国信事务受命者。", "biography": null, "status": "draft", "id": "b5a0d45a-e4ba-5230-bd2f-56bced660fbf"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "郭威于壬子渡河，住宿澶州", "start_year": 950, "end_year": 950, "time_original": "950年十二月壬子", "dynasty": "五代十国", "description": "郭威于壬子渡河，住宿澶州。", "phases": [], "location_name": "澶州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "41fb1253-b280-583a-a654-f42a7b93cbd7"}, {"title": "澶州将士于癸丑早晨闯入郭威住处，要求他做皇帝", "start_year": 950, "end_year": 950, "time_original": "950年十二月癸丑早晨", "dynasty": "五代十国", "description": "郭威准备出发时，数千将士突然喧闹；郭威命人关门，将士翻墙登屋闯入，说他们已与刘氏结仇，要求郭威亲自做皇帝，不能再立刘氏。", "phases": [], "location_name": "澶州郭威住处", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2d73d86a-d84a-51be-b392-7d0a9f3276c8"}, {"title": "将士将撕裂的黄旗披在郭威身上，拥他南行", "start_year": 950, "end_year": 950, "time_original": "950年十二月癸丑", "dynasty": "五代十国", "description": "将士将撕裂的黄旗披在郭威身上，拥他南行。", "phases": [], "location_name": "澶州至南行路上", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "31444a32-34cc-5d6c-aa9b-86810aa1cf51"}, {"title": "郭威上书李太后，表示愿供奉汉宗庙、像对待母亲一样侍奉太后", "start_year": 950, "end_year": 950, "time_original": "950年十二月癸丑军变后至丙辰前，具体上书日未载", "dynasty": "五代十国", "description": "郭威上书李太后，表示愿供奉汉宗庙、像对待母亲一样侍奉太后。", "phases": [], "location_name": "南行途中、后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "08919c96-c9d9-5ec8-b9f1-5d20d9b44d3c"}, {"title": "郭威于丙辰到韦城，发书安抚大梁士民", "start_ye