SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "郭威于壬子渡河，住宿澶州。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：壬子，郭威渡河，馆于澶州。；核对说明：馆为住宿驻扎，不写建新官署。", "status": "draft", "id": "c498f6a9-25d5-5084-9a58-73bf3e1d2d4e", "subject_id": "41fb1253-b280-583a-a654-f42a7b93cbd7", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年十二月壬子", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：壬子，郭威渡河，馆于澶州。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "176e47db-9632-5767-89e8-3ede8f5fb1a8", "subject_id": "41fb1253-b280-583a-a654-f42a7b93cbd7", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "person", "field_path": "description", "claim_text": "郭威：渡河后住宿澶州。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：壬子，郭威渡河，馆于澶州。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "4b773f06-5c02-5f41-be9e-028afa07966e", "subject_id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "郭威：渡河后住宿澶州。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：壬子，郭威渡河，馆于澶州。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "61ddd8d8-de3e-500c-bee5-7dbf22ca5e0e", "subject_id": "e3f8cedc-692a-5e34-81cd-ce07f977c00e", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "《旧五代史》也记郭威壬子到澶州，但把将士拥立和南还也记在当日。", "citation": "《旧五代史》卷一百〇三，段落 jiu-wudaishi-205deb4a7860-p002502；EPUB电子本，纸本及异文待核", "note": "原文：壬子，樞密使郭威次澶州，何福進已下及諸軍將士，扶擁威請為天子，即日南還。；核对说明：通鉴壬子抵达、癸丑兵变，《旧五代史》本纪壬子兼记兵变，纪日差异保留。", "status": "draft", "id": "db76fe3a-e24c-59b6-b7d5-e0d2dba541c4", "subject_id": "41fb1253-b280-583a-a654-f42a7b93cbd7", "source_id": "58b01b09-5220-5d32-93ca-6bbb7fcb25bb"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "《新五代史》将郭威到澶州并返回记在癸丑。", "citation": "《新五代史》卷11·周本纪·十二月北返与监国，段落 xin-wudaishi-b08f244b9241-p000367；已核上下文及传主，纸本及异文待核。", "note": "原文：癸丑，至澶州而旋。；核对说明：《新五代史》本纪到达日与通鉴壬子不同，不合并成唯一日期。", "status": "draft", "id": "1bd55bee-a25e-5095-a58c-8a84120b9130", "subject_id": "41fb1253-b280-583a-a654-f42a7b93cbd7", "source_id": "becceed3-0d3e-5ed2-adf2-777205288c13"}, {"subject_table": "event", "field_path": "description", "claim_text": "郭威准备出发时，数千将士突然喧闹；郭威命人关门，将士翻墙登屋闯入，说他们已与刘氏结仇，要求郭威亲自做皇帝，不能再立刘氏。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：癸丑旦，将发，将士数千人忽大噪。威命闭门，将士逾垣登屋而入曰：“天子须侍中自为之，将士已与刘氏为仇，不可立也！”；核对说明：数千是原载规模，未具名将士不造名单；将士关于结仇和不能立的说法不写为刘赟已下报复令。", "status": "draft", "id": "72d66128-2a95-53f4-8741-755dc6e35db1", "subject_id": "2d73d86a-d84a-51be-b392-7d0a9f3276c8", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年十二月癸丑早晨", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：癸丑旦，将发，将士数千人忽大噪。威命闭门，将士逾垣登屋而入曰：“天子须侍中自为之，将士已与刘氏为仇，不可立也！”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "c5e4eac2-04b5-5f96-9ccc-5c92ad06b029", "subject_id": "2d73d86a-d84a-51be-b392-7d0a9f3276c8", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "郭威：命令关门，面对将士闯入要求拥立。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：癸丑旦，将发，将士数千人忽大噪。威命闭门，将士逾垣登屋而入曰：“天子须侍中自为之，将士已与刘氏为仇，不可立也！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b5f6d380-bba1-5b0e-93e0-95c277c94a6d", "subject_id": "d3fdd18e-1aac-5ea7-8126-edcf5c79076a", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "event", "field_path": "description", "claim_text": "将士将撕裂的黄旗披在郭威身上，拥他南行。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：或裂黄旗以被威体，共扶抱之，呼万岁震地，因拥威南行。；核对说明：原文黄旗，不能改成赵匡胤陈桥黄袍；军中呼万岁与正式即位分开。被拥不证明没有事先策划，也不凭猜测写有策划。", "status": "draft", "id": "6aefa877-a176-5900-90fe-74e6e925208b", "subject_id": "31444a32-34cc-5d6c-aa9b-86810aa1cf51", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年十二月癸丑", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：或裂黄旗以被威体，共扶抱之，呼万岁震地，因拥威南行。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "18dce700-ce44-5352-ac65-324690064f59", "subject_id": "31444a32-34cc-5d6c-aa9b-86810aa1cf51", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "郭威：被将士披黄旗、扶拥南行。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：或裂黄旗以被威体，共扶抱之，呼万岁震地，因拥威南行。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "7e935e1b-2216-5dc2-82a3-f830d7a778f5", "subject_id": "d4380f38-78bc-5761-8cdb-d920436d39c3", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "event", "field_path": "description", "claim_text": "郭威上书李太后，表示愿供奉汉宗庙、像对待母亲一样侍奉太后。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：威乃上太后笺，请奉汉宗庙，事太后为母。；核对说明：愿奉与事为政治承诺，不建立血缘母子或已完成收养礼关系，也不写汉宗庙永久获保。", "status": "draft", "id": "c1911f47-49af-509a-8a22-f77ee462564f", "subject_id": "08919c96-c9d9-5ec8-b9f1-5d20d9b44d3c", "source_id": "15f95022-6fdc-5e57-87e3-bb96b4976d8d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年十二月癸丑军变后至丙辰前，具体上书日未载", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p077·原文件第82行", "note": "原文：威乃上太后笺，请奉汉宗庙，事太后为母。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "291e1cb2-26c5-5c04-9487-61ac70014cd6", "subject_id": "08919c96-c9d9-5ec8-